14	std::complex<double> Fvf(int st, int j1, int j2, int j3, int j4, int j5, int j6,
15	                          FArray2D<std::complex<double>>& za,
16	                          FArray2D<std::complex<double>>& zb) {
17	    using namespace heldefs_mod;
18	    using namespace mxpart_mod;
19	    using namespace sprods_com_mod;
20	
21	    auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) -> std::complex<double> {
22	        return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4);
23	    };
24	
25	    std::complex<double> I3m123456 = i3m(s(j1,j2), s(j3,j4), s(j5,j6));
26	    std::complex<double> I3m563412 = I3m123456;
27	
28	    std::complex<double> result = 0.0;
29	
30	    if (st == hqpqbmgpgm) {
31	        result =
32	            -std::pow(zab2(j5,j2,j4,j1),2)/(za(j5,j6)*zb(j1,j2)*std::pow(zab2(j3,j1,j2,j4),2))
33	            *Lsm1_2mh(s(j3,j4),t(j1,j2,j4),s(j1,j2),s(j5,j6))
34	            -std::pow(zab2(j2,j1,j3,j6),2)/(za(j1,j2)*zb(j5,j6)*std::pow(zab2(j3,j1,j2,j4),2))
35	            *Lsm1_2mh(s(j3,j4),t(j1,j2,j3),s(j1,j2),s(j5,j6))
36	            -I3m123456*za(j4,j5)*zb(j1,j3)
37	            *zab2(j2,j1,j3,j6)/(2.0*zab2(j3,j1,j2,j4)*t(j1,j2,j3))
38	            -I3m123456*za(j2,j4)*zb(j3,j6)
39	            *zab2(j5,j2,j4,j1)/(2.0*zab2(j3,j1,j2,j4)*t(j1,j2,j4))
40	            +I3m563412*za(j2,j4)*zb(j3,j6)
41	            *zab2(j5,j3,j6,j1)/(2.0*zab2(j3,j1,j2,j4)*t(j3,j5,j6))
42	            +I3m563412*za(j4,j5)*zb(j1,j3)
43	            *zab2(j2,j4,j5,j6)/(2.0*zab2(j3,j1,j2,j4)*t(j4,j5,j6));
44	    } else if (st == hqpqbmgpgp) {
45	        result =
46	            -std::pow(za(j2,j5),2)/(za(j1,j2)*za(j5,j6)*std::pow(za(j3,j4),2))
47	            *Lsm1_2me(t(j1,j2,j3),t(j1,j2,j4),s(j1,j2),s(j5,j6));
48	    }
49	
50	    return result; // @coverage-probe
51	}
