53	extern "C" {
54	  std::complex<double> fvf_wrapper(int st, int j1, int j2, int j3, int j4, int j5, int j6,
55	                                   std::complex<double>* fza, std::complex<double>* fzb) {
56	    using namespace mxpart_mod;
57	    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
58	    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
59	    return Fvf(st, j1, j2, j3, j4, j5, j6, za, zb);
60	  }
